   "id": "z57572ada",
   "sez": "mondo",
   "titolo": "La senatrice Gillibrand: i democratici devono porre fine alla guerra in Iran",
   "orig": "Sen. Gillibrand says Democrats must end Iran war, hold Trump accountable. But how?",
   "lead": "La senatrice democratica Kirsten Gillibrand ha dichiarato che il suo partito deve impegnarsi per porre fine alla guerra in Iran e chiedere conto all'amministrazione Trump, in un'intervista rilasciata al programma Morning Edition. Gillibrand ha indicato tra le priorità dei democratici anche la riduzione dei costi per i cittadini, ma restano aperte domande su come il partito intenda concretamente realizzare questi obiettivi dopo la vittoria alle elezioni di metà mandato. Lo riferisce NPR.",
   "more": [
    "Gli Stati Uniti sono coinvolti in un conflitto con l'Iran che ha diviso l'opinione pubblica americana. Dopo la vittoria democratica alle elezioni di metà mandato, il partito si trova a dover tradurre le promesse elettorali in azioni concrete, nonostante i limiti costituzionali ai poteri del Congresso in materia di politica estera."
   ],
