   "sez": "tech",
   "titolo": "OpenAI cerca di convincere gli elettori sui data center dopo le sconfitte elettorali",
   "orig": "OpenAI tenta mudar opinião dos eleitores sobre centros de dados após derrota na intercalares norte-americanas",
   "lead": "Dopo che candidati favorevoli a regole più severe sui data center hanno vinto in diversi stati americani alle elezioni di metà mandato, OpenAI ha annunciato nuove misure per conquistare il sostegno delle comunità locali. Secondo Clarín, l'azienda ha lanciato un quadro regolatorio per i propri data center, impegnandosi a coprire i costi di infrastrutture e a prevedere consultazioni comunitarie, nel tentativo di alleviare le preoccupazioni ambientali ed economiche emerse durante la campagna elettorale.",
   "more": [
    "L'espansione dei data center necessari per addestrare e far funzionare i modelli di intelligenza artificiale richiede grandi quantità di energia e acqua, generando opposizione locale in diverse aree degli Stati Uniti. Le aziende tecnologiche cercano ora di anticipare le critiche con impegni di investimento e trasparenza verso le comunità coinvolte."
   ],
