   "id": "z4de18186",
   "sez": "salute",
   "titolo": "Test non invasivi per la MASH: differenze tra pratica clinica e studi",
   "orig": "[Comment] Non-invasive tests in MASH: clinical practice versus trials",
   "lead": "Un commento pubblicato su The Lancet analizza il ruolo dei test non invasivi nella malattia epatica steatosica disfunzionale metabolica, strumenti centrali per le decisioni cliniche, la stratificazione del rischio, i percorsi di invio agli specialisti e il reclutamento negli studi clinici. Con la crescente disponibilità di trattamenti farmacologici per la steatoepatite associata a disfunzione metabolica, è aumentata l'importanza di identificare correttamente lo stadio di fibrosi del fegato, anche se l'obiettivo dei test cambia tra uso clinico e sperimentazione. Lo riferisce The Lancet.",
   "more": [
    "La steatosi epatica associata a disfunzione metabolica è una malattia del fegato legata a sovrappeso, diabete e altri fattori metabolici, in crescita a livello globale. I test non invasivi, come esami del sangue o tecniche di imaging, permettono di valutare il danno al fegato senza ricorrere alla biopsia, pur con margini diversi di precisione rispetto a quest'ultima."
   ],
