   "id": "z660d8709",
   "sez": "viaggi",
   "titolo": "La strategia Ue per un turismo sostenibile non ha fondi né obiettivi misurabili",
   "orig": "EU’s Sustainable Tourism Plan Aims to Spread Visitors Out — With No Funding or Targets",
   "lead": "La Commissione europea ha presentato una strategia per il turismo sostenibile pensata a distribuire meglio i visitatori nei paesi membri, ma secondo Skift il piano si aggiunge a strategie turistiche già esistenti senza prevedere finanziamenti né obiettivi quantificabili che ne garantiscano l'effettiva attuazione. Il documento punta a ridurre la concentrazione di turisti in poche destinazioni molto frequentate, ma resta privo di strumenti concreti per sostenerne la realizzazione. Lo riferisce Skift.",
   "more": [
    "Il sovraffollamento turistico in alcune città e aree europee è un problema crescente, con proteste di residenti in diverse destinazioni molto visitate. Le strategie europee sul turismo sostenibile puntano a redistribuire i flussi verso aree meno conosciute, ma la loro efficacia dipende spesso da risorse e strumenti di attuazione concreti, non sempre previsti."
   ],
