   "id": "z22f93291",
   "sez": "manga",
   "titolo": "Gipi pubblica un nuovo fumetto a puntate sul Quotidiano Nazionale",
   "orig": "Gipi pubblica un nuovo fumetto a puntate sul Quotidiano Nazionale",
   "lead": "Il fumettista Gipi ha iniziato a pubblicare un nuovo fumetto a puntate sulle pagine del Quotidiano Nazionale, con una striscia al giorno per circa 60 uscite complessive. Le tavole saranno leggibili anche online, oltre che in edicola. L'iniziativa prosegue la tradizione dei fumetti a puntate sui quotidiani italiani, offrendo un nuovo progetto narrativo firmato da uno degli autori italiani più noti del fumetto contemporaneo. Lo riferisce Fumettologica.",
   "more": [
    "Gipi, pseudonimo di Gianni Pacinotti, è uno degli autori di fumetti italiani più premiati a livello internazionale, noto per opere come \"Unastoria\" e \"La terra dei figli\". La pubblicazione a puntate su quotidiani è una formula storica che permette di raggiungere un pubblico ampio al di fuori del circuito tradizionale del fumetto."
   ],
