   "id": "z87ce1ef4",
   "sez": "mondo",
   "titolo": "In Inghilterra una colonia di sterne torna a popolarsi dopo l'influenza aviaria",
   "orig": "Miracle Recovery Sees Seabirds Reclaim Former Colony After Avian Flu Wiped Them Out",
   "lead": "Lungo la costa meridionale dell'Inghilterra una colonia di sterne maggiori è tornata a popolarsi tre anni dopo essere stata azzerata dall'influenza aviaria. Grazie a interventi di conservazione, gli uccelli sono passati da zero a 756 esemplari. Nella stessa area sono tornati anche fraticelli, corrieri grossi, gabbiani comuni e beccacce di mare. Lo riferisce Good News Network.",
   "more": [
    "L'influenza aviaria ha colpito duramente le popolazioni di uccelli marini in Europa negli ultimi anni, causando morie di massa in diverse colonie costiere. Il recupero di una colonia azzerata è considerato un caso raro, reso possibile da misure di protezione dell'habitat e monitoraggio costante da parte di associazioni ambientaliste locali."
   ],
