   "id": "z4f8562d4",
   "sez": "economia",
   "titolo": "Debito estero dei paesi in via di sviluppo a un record di 9.400 miliardi di dollari",
   "orig": "Developing countries’ external debt hits record $9.4tn — World Bank",
   "lead": "Il debito estero dei paesi in via di sviluppo ha raggiunto un livello record di 9.400 miliardi di dollari nel 2025, secondo un rapporto della Banca Mondiale. L'aumento è legato alla crescita dei prestiti da creditori privati, saliti di quasi il 35% a 251 miliardi di dollari, e ai tassi di interesse più elevati. Il debito è cresciuto più rapidamente tra i paesi più poveri. La Banca Mondiale avverte che l'onere debitorio crescente rischia di scoraggiare gli investimenti necessari allo sviluppo.",
   "more": [
    "Il debito estero dei paesi in via di sviluppo è monitorato annualmente dalla Banca Mondiale. Negli ultimi anni l'aumento dei tassi di interesse globali e la minore disponibilità di finanziamenti concessionali hanno spinto molti governi a rivolgersi a creditori privati, con condizioni spesso più onerose per la stabilità finanziaria dei paesi più fragili."
   ],
