   "id": "z8080acdd",
   "sez": "cultura",
   "titolo": "La Repubblica Ceca riceve libri rari dalle comunità ceco-americane",
   "orig": "Czechia receives rare books and publications from Czech-American communities",
   "lead": "La Repubblica Ceca ha ricevuto una collezione di libri e pubblicazioni storiche dalle comunità di emigranti cechi e slovacchi negli Stati Uniti. La consegna è avvenuta durante una cerimonia al Palazzo Černín di Praga martedì. Il materiale documenta la storia culturale delle comunità ceco-americane. Lo riferisce Radio Prague International.",
   "more": [
    "Le comunità ceche e slovacche emigrate negli Stati Uniti nel corso del Novecento hanno conservato archivi e pubblicazioni che testimoniano la vita culturale e politica delle diaspore, spesso donati o restituiti alle istituzioni dei paesi d'origine come forma di preservazione della memoria storica."
   ],
