   "sez": "salute",
   "titolo": "A Betlemme il primo polo di chirurgia pediatrica diurna della Cisgiordania",
   "orig": "Betlemme, il primo polo di chirurgia pediatrica diurna della Cisgiordania",
   "lead": "A Betlemme è stato inaugurato il primo polo di chirurgia pediatrica diurna della Cisgiordania, all'interno del Caritas Baby Hospital. Il nuovo padiglione, chiamato \"Ala del Giubileo\", permetterà ai piccoli pazienti di essere operati senza dover affrontare spostamenti, richieste di permessi alle autorità israeliane o lunghe attese ai checkpoint. Il progetto è stato realizzato grazie al supporto di associazioni come Aiuto Bambini Betlemme. Lo riferisce Vatican News.",
   "more": [
    "I checkpoint israeliani in Cisgiordania rendono spesso difficili e lunghi gli spostamenti dei palestinesi, incluso l'accesso a cure mediche specialistiche. Poter operare i bambini direttamente a Betlemme riduce quindi tempi e ostacoli logistici per le famiglie che necessitano di interventi chirurgici pediatrici."
   ],
