   "sez": "adolescenti",
   "titolo": "Sondaggio: per oltre un italiano su due il riscatto dei giovani ex detenuti è possibile",
   "orig": "Per oltre un italiano su due il riscatto dei giovani è possibile: i numeri sul reinserimento dopo un passato in carcere",
   "lead": "Secondo un sondaggio riportato da Orizzonte Scuola, oltre un italiano su due (58%) ritiene possibile il riscatto di un giovane con un passato giudiziario, mentre l'87% chiede una formazione professionale concreta per favorirne il reinserimento. Il 40% individua nel lavoro l'ostacolo più difficile da superare per chi è uscito dal carcere. I dati mostrano una società che non ha perso fiducia nei ragazzi più fragili, pur riconoscendone le difficoltà. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il reinserimento sociale dei giovani con precedenti giudiziari passa spesso attraverso percorsi di formazione professionale e inserimento lavorativo, strumenti considerati decisivi per ridurre il rischio di recidiva, ma frenati da pregiudizi sociali e difficoltà di accesso al mercato del lavoro."
   ],
