   "titolo": "Sudafrica, il Tesoro: la revisione del Pil riduce il rapporto debito/Pil e migliora le prospettive fiscali",
   "orig": "South Africa’s GDP rebasing lowers debt ratio, improves fiscal outlook, Treasury says",
   "lead": "Il Tesoro nazionale del Sudafrica ha comunicato che la recente revisione del Prodotto interno lordo del Paese ha abbassato il rapporto debito/Pil, migliorando le prospettive sui conti pubblici. La revisione, nota come 'rebasing', aggiorna i dati economici di riferimento usati per calcolare gli indicatori di bilancio. Lo riferisce The Citizen.",
   "more": [
    "Il 'rebasing' del Pil è un aggiornamento periodico del metodo di calcolo della ricchezza nazionale, che tiene conto di nuovi settori economici o di dati più recenti. Spesso porta a stimare un Pil più alto rispetto a quello precedente, riducendo di conseguenza, a parità di debito, il rapporto debito/Pil usato dagli investitori per valutare la sostenibilità fiscale di un Paese."
   ],
