   "sez": "mondo",
   "titolo": "Petroliere di diesel russo dirette negli Usa cambiano rotta, dubbi sull'accordo Trump-Putin",
   "orig": "Two tankers headed to US under Trump-Putin diesel deal change course",
   "lead": "Due petroliere che trasportavano diesel russo verso gli Stati Uniti, nell'ambito di un accordo tra Trump e Putin, hanno cambiato rotta. Una nave ha modificato il segnale indicando come destinazione il Brasile, mentre un'altra si è diretta verso il Mediterraneo segnalando di essere 'in attesa di ordini' al largo dell'Algeria. L'episodio alimenta dubbi sulla reale attuazione dell'accordo tra Washington e Mosca. Lo riferisce Meduza, citando il Financial Times.",
   "more": [
    "Gli accordi energetici tra Stati Uniti e Russia restano complicati dalle sanzioni occidentali imposte dopo l'invasione dell'Ucraina del 2022, che limitano l'acquisto di prodotti petroliferi russi. Il tracciamento satellitare delle petroliere è spesso usato per monitorare rotte sospette o elusione delle sanzioni internazionali."
   ],
