   "id": "z0dee300c",
   "sez": "prima",
   "titolo": "Midterm Usa, i repubblicani scaricano il segretario alla Difesa Hegseth dopo la sconfitta elettorale",
   "orig": "Midterm, Repubblicani scaricano Heghseth",
   "lead": "Dopo la sconfitta alle elezioni di metà mandato negli Stati Uniti, molti nel Partito repubblicano attribuiscono al segretario alla Difesa Pete Hegseth parte della responsabilità della disfatta, legandola alla decisione di attaccare l'Iran. Donald Trump ha detto alla rete Abc News di aver ricevuto lamentele su Hegseth ma di volerlo mantenere al suo posto. Nel Pentagono si registra una resa dei conti interna tra alti funzionari, mentre anche il segretario di Stato Marco Rubio valuterebbe le dimissioni per prendere le distanze da Trump in vista del 2028. Lo riferisce Rai News, con ANSA, la Repubblica e Il Messaggero.",
   "more": [
    "Le elezioni di metà mandato, o midterm, si tengono a metà del mandato presidenziale e rinnovano parte del Congresso. Una sconfitta pesante del partito del presidente spesso apre fasi di scontro interno su strategie e responsabilità, soprattutto quando si avvicinano le primarie per le elezioni presidenziali successive, previste nel 2028."
   ],
