   "id": "z434964d3",
   "sez": "mondo",
   "titolo": "Stati Uniti, una città della California autorizza la registrazione ufficiale delle unioni poliamorose",
   "orig": "États-Unis : cette ville autorise l'enregistrement officiel des unions polyamoureuses",
   "lead": "La città di West Hollywood, in California, ha deciso di permettere alle persone impegnate in relazioni con più partner di registrare ufficialmente la propria unione presso il municipio. La decisione dà accesso a determinate protezioni legali, ma non garantisce gli stessi diritti riconosciuti alle coppie sposate. Lo riferisce La Nouvelle Tribune.",
   "more": [
    "West Hollywood è nota per politiche progressiste su temi di genere e relazioni, essendo una delle prime città statunitensi ad aver introdotto il registro delle unioni domestiche per le coppie non sposate negli anni Ottanta. Il poliamore indica relazioni sentimentali consensuali con più di due partner."
   ],
