   "id": "z5667f2ce",
   "sez": "mondo",
   "titolo": "Israele, la Lista Unita araba sostiene Eisenkot per formare il nuovo governo",
   "orig": "Joint List says it will back Eisenkot to form Israel’s next government",
   "lead": "La Lista Unita, coalizione di partiti arabi israeliani che ha ottenuto un record di 19 seggi su 120 alla Knesset nelle ultime elezioni, ha annunciato che sosterrà Gadi Eisenkot per formare il nuovo governo. Tutti i partiti a maggioranza araba hanno appoggiato la sua candidatura nei colloqui con il presidente israeliano. Secondo il capo della Lista Unita Yousef Jabareen, l'endorsement punta a un miglioramento per tutti i cittadini, in particolare per gli arabi. Lo riferiscono Al Jazeera e Haaretz.",
   "more": [
    "Gadi Eisenkot è un ex capo di stato maggiore dell'esercito israeliano, entrato in politica dopo la guerra a Gaza iniziata nel 2023. I partiti arabi israeliani, che rappresentano circa un quinto della popolazione del Paese, raramente entrano in coalizioni di governo, ma il loro sostegno parlamentare può risultare decisivo nella formazione di un nuovo esecutivo."
   ],
