   "id": "zbac7fbe7",
   "sez": "mondo",
   "titolo": "Nigeria, un tribunale annulla la candidatura di Atiku Abubakar e azzera la leadership del partito ADC",
   "orig": "Nigeria: Court Nullifies Atiku's Candidacy, Sacks All ADC Candidates, Party Leadership",
   "lead": "Un tribunale nigeriano ha annullato la candidatura dell'ex vicepresidente Atiku Abubakar come candidato presidenziale del partito African Democratic Congress (ADC) per le elezioni di gennaio, e ha destituito tutta la leadership del partito. Se la sentenza fosse confermata dai tribunali superiori, l'ADC, principale sfidante del partito di governo APC, non potrebbe presentare candidati alle prossime elezioni generali. Lo riferiscono allAfrica e The Straits Times.",
   "more": [
    "L'ADC si era affermato negli ultimi anni come principale alleanza di opposizione in Nigeria, raccogliendo diversi ex membri di partiti rivali in vista delle elezioni presidenziali. Le contestazioni legali su candidature e leadership di partito sono frequenti nel sistema politico nigeriano, spesso usate come strumento per indebolire gli avversari prima del voto."
   ],
