   "id": "z5a5578dd",
   "sez": "mondo",
   "titolo": "Un mese dopo l'offensiva del governo yemenita, la guerra di logoramento continua",
   "orig": "A month after Yemen government offensive began, war of attrition takes hold",
   "lead": "A un mese dall'inizio dell'offensiva lanciata dal governo yemenita, il conflitto si è trasformato in una guerra di logoramento. Secondo Al Jazeera, gli Houthi hanno subito perdite significative ma continuano a infliggere danni alle forze governative e all'Arabia Saudita. La situazione sul terreno resta instabile, con nessuna delle due parti in grado di ottenere una vittoria decisiva dopo un mese di combattimenti. Lo riferisce Al Jazeera.",
   "more": [
    "Il conflitto yemenita vede da anni il governo riconosciuto internazionalmente, sostenuto da una coalizione guidata dall'Arabia Saudita, contrapposto ai ribelli Houthi, che controllano ampie zone del paese incluso la capitale Sanaa. La guerra ha causato una delle peggiori crisi umanitarie al mondo."
   ],
