   "titolo": "Esperti armeni e turchi discutono di collaborazione alla COP17 di Yerevan",
   "orig": "Experts from Armenia and Turkey discuss collaboration at COP17 in Yerevan",
   "lead": "Alla COP17 di Yerevan, esperti provenienti da Armenia e Turchia hanno discusso possibili forme di collaborazione sulla biodiversità, sottolineando che il tema non conosce confini nazionali. Secondo Bianet, i partecipanti hanno evidenziato come l'incontro renda più facile collegare le esperienze dei due paesi su questioni ambientali comuni. L'iniziativa si inserisce nel più ampio percorso della conferenza delle parti dedicata alla biodiversità, che riunisce delegazioni da diversi paesi. Lo riferisce Bianet.",
   "more": [
    "La COP sulla biodiversità è un vertice internazionale periodico in cui i paesi discutono strategie comuni per la protezione degli ecosistemi e delle specie minacciate. Armenia e Turchia, pur avendo relazioni diplomatiche storicamente complesse, condividono ecosistemi transfrontalieri che richiedono forme di cooperazione ambientale."
   ],
