   "id": "z2303e728",
   "sez": "dibattito",
   "titolo": "Sette italiani su dieci preoccupati per lo spopolamento delle aree interne",
   "orig": "Aree interne, in Italia sette persone su dieci preoccupate per lo spopolamento",
   "lead": "Secondo un sondaggio Demopolis presentato in occasione dei vent'anni della Fondazione con il Sud a Napoli, sette italiani su dieci si dicono preoccupati per lo spopolamento delle aree interne del paese. L'evento, alla presenza del presidente della Repubblica Sergio Mattarella, ha visto la presentazione della campagna 'Sud vivo', dedicata alla rigenerazione di territori e comunità. Secondo dati Istat citati dalla Fondazione, tra il 2001 e il 2023 il Mezzogiorno ha perso circa 730mila residenti. La Fondazione propone interventi per contrastare l'abbandono dei territori, senza che le fonti riportino posizioni contrarie sul tema.",
   "more": [
    "Lo spopolamento delle aree interne e del Mezzogiorno italiano è un fenomeno legato a bassa natalità, emigrazione verso il Nord e verso l'estero, e carenza di servizi e opportunità lavorative nei piccoli centri. Il tema è oggetto di politiche pubbliche e progetti di rigenerazione territoriale da diversi anni."
   ],
