   "sez": "ambiente",
   "titolo": "Singapore termina la distribuzione di mascherine N95 con l'attenuarsi della foschia",
   "orig": "Singapore to end N95 mask distribution on Saturday as haze abates",
   "lead": "Singapore porrà fine sabato alla distribuzione di mascherine N95 alla popolazione, man mano che la foschia atmosferica si attenua. Secondo CNA, la decisione segue il miglioramento delle condizioni dell'aria nel paese dopo il periodo di inquinamento legato agli incendi boschivi transfrontalieri nella regione. La misura accompagna il miglioramento della qualità dell'aria registrato nelle ultime settimane a Singapore. Lo riferisce CNA.",
   "more": [
    "La foschia che colpisce periodicamente il Sud-est asiatico è causata soprattutto dagli incendi legati alla deforestazione in Indonesia, che diffondono particolato fine nell'aria di paesi vicini come Singapore e Malesia, spingendo i governi ad adottare misure di protezione sanitaria e sanzioni contro i responsabili."
   ],
