   "titolo": "La Russia potrebbe aver provato un attacco a un satellite finlandese",
   "orig": "Russian Military May Have Rehearsed Attack on Finnish Satellite, Specialist Warns",
   "lead": "A metà ottobre un satellite militare russo si sarebbe avvicinato a X36, satellite della società finlandese ICEYE che fornisce immagini radar a governi e militari occidentali, inclusa l'Ucraina. Un esperto avverte che la manovra potrebbe essere stata una simulazione di attacco. Lo riferisce Moscow Times.",
   "more": [
    "I satelliti radar come quelli di ICEYE forniscono immagini ad alta risoluzione utili per il monitoraggio militare anche in condizioni di nuvolosità o buio, risultando strategici nel conflitto in Ucraina. Avvicinamenti ravvicinati tra satelliti militari e civili vengono spesso interpretati come test di capacità offensive nello spazio."
   ],
