   "sez": "tech",
   "titolo": "Hacker nordcoreani presi di mira esperti IT in Estonia",
   "orig": "North Korean hackers are targeting Estonia's IT experts, report finds",
   "lead": "Un'inchiesta rivela che hacker legati alla Corea del Nord stanno conducendo attacchi informatici sofisticati contro esperti informatici in Estonia, compreso uno dei tecnici più noti del paese. La notizia sorprende perché la Corea del Nord è generalmente associata a uno scarso accesso della popolazione alla tecnologia, mentre in Estonia le minacce cyber più discusse provengono di solito da Russia e Cina. Lo riferisce ERR News.",
   "more": [
    "La Corea del Nord gestisce gruppi di hacker statali, come Lazarus, usati per spionaggio e furto di criptovalute, nonostante l'isolamento tecnologico della popolazione civile. L'Estonia, paese digitalmente avanzato, è spesso target di attacchi cyber data la sua infrastruttura informatizzata e la vicinanza geopolitica alla Russia."
   ],
