   "id": "z66fde466",
   "sez": "economia",
   "titolo": "La Cina blocca l'acquisizione da 5,4 miliardi di dollari di SoftBank su ABB Robotics",
   "orig": "China blocks SoftBank’s US$5.4 billion takeover of ABB’s robotics division",
   "lead": "L'autorità cinese che supervisiona gli investimenti strategici ha comunicato a SoftBank che non autorizzerà l'acquisizione, da 5,4 miliardi di dollari, della divisione robotica del gruppo svizzero ABB. Lo ha reso noto giovedì la stessa ABB. È il secondo grande accordo bloccato da Pechino quest'anno, dopo l'ordine di smantellamento dell'acquisizione da parte di Meta della startup di intelligenza artificiale Manus. La decisione arriva mentre Pechino intensifica i controlli sugli investimenti estranieri in startup nazionali tecnologiche.",
   "more": [
    "SoftBank è un conglomerato giapponese di investimenti con forti interessi in tecnologia e robotica. ABB è un gruppo svizzero di ingegneria industriale. Il blocco cinese riflette una tendenza crescente di Pechino a proteggere settori tecnologici strategici, inclusa la robotica, da controllo o influenza straniera."
   ],
