   "id": "z128f6c55",
   "sez": "economia",
   "titolo": "Lavoro domestico, oltre metà del settore è irregolare in Italia",
   "orig": "Lavoro domestico, oltre metà del settore è nel sommerso (56,6%). Famiglie schiacciate dal caro-servizi (+20%)",
   "lead": "Secondo i dati diffusi da Assindatcolf, il 56,6% del lavoro domestico in Italia è in nero, mentre le famiglie che impiegano badanti devono fronteggiare costi in crescita del 20%. Il 65,4% delle famiglie che si avvale di una o più badanti spende oltre 1.500 euro al mese, e il 28,9% supera i 2.000 euro mensili. Il settore è cresciuto del 7,6% nel triennio 2023-2025, ma la distanza tra bisogni e risorse disponibili spinge le famiglie a scelte sempre più difficili.",
   "more": [
    "Il lavoro domestico in Italia, che comprende colf e badanti, è storicamente caratterizzato da alti livelli di irregolarità contrattuale, legati ai costi elevati per le famiglie e alla carenza di sostegni pubblici. Assindatcolf è l'associazione datoriale di riferimento per i datori di lavoro domestico nel paese."
   ],
