   "id": "z17a3fc0e",
   "sez": "economia",
   "titolo": "L'azienda aeronautica gallese AerFin acquistata per 475 milioni di sterline",
   "orig": "Welsh aviation firm AerFin bought in £475m deal",
   "lead": "AerFin, società gallese specializzata in aviazione e precedentemente controllata in maggioranza da un fondo di private equity, è stata acquistata in un'operazione dal valore di 475 milioni di sterline. L'azienda ha dichiarato che l'operazione segna l'inizio di una \"nuova fase\" per la sua attività. Non sono stati forniti ulteriori dettagli sull'acquirente o sulle motivazioni specifiche dell'operazione. La vendita riguarda un'impresa attiva nel settore della manutenzione e del commercio di componenti aeronautici. Lo riferisce BBC News.",
   "more": [
    "Il settore della manutenzione aeronautica e della vendita di componenti per aerei è cresciuto negli ultimi anni grazie alla ripresa del traffico aereo dopo la pandemia, attirando l'interesse di fondi di investimento e gruppi industriali alla ricerca di aziende specializzate in ricambi e revisione di flotte."
   ],
