   "id": "z366ed612",
   "sez": "prima",
   "titolo": "La Finlandia condanna capitano ed equipaggio per il sabotaggio di cavi nel Baltico",
   "orig": "Finland court jails captain and crew member over Baltic cable sabotage",
   "lead": "Un tribunale finlandese ha condannato il capitano russo della nave Fitburg a tre anni e mezzo di carcere per il sospetto sabotaggio di cavi sottomarini tra Helsinki e Tallinn, avvenuto lo scorso anno. Il nostromo della nave ha ricevuto una pena di due anni e dieci mesi, mentre un marinaio azerbaigiano è stato condannato a tre anni per danneggiamento aggravato. La nave era stata sequestrata dalla Finlandia dopo l'incidente, uno dei numerosi casi di infrastrutture danneggiate nel Baltico dall'inizio dell'invasione russa dell'Ucraina.",
   "more": [
    "Dal 2022 si sono verificati diversi episodi di danneggiamento di cavi sottomarini e gasdotti nel Mar Baltico, attribuiti talvolta a incidenti e in altri casi a sospetti sabotaggi. I paesi della regione hanno rafforzato la sorveglianza marittima temendo possibili azioni ostili legate alle tensioni con la Russia dopo l'invasione dell'Ucraina."
   ],
