   "id": "z5a7b94c9",
   "sez": "mondo",
   "titolo": "Un alto funzionario nordcoreano visita la Cina dopo il viaggio di Kim Jong Un",
   "orig": "Senior North Korean party official visits China on heels of Kim Jong Un trip",
   "lead": "Kim Song Nam, direttore del dipartimento internazionale del Partito dei Lavoratori di Corea, è arrivato a Pechino per una visita ufficiale su invito delle autorità cinesi. Il viaggio avviene dieci giorni dopo che il funzionario aveva accompagnato il leader nordcoreano Kim Jong Un in una visita alla città cinese di confine di Dandong. L'arrivo rientra in un rafforzamento della diplomazia tra i due paesi dopo la visita di Kim Jong Un in Cina. Lo riferisce NK News.",
   "more": [
    "La Corea del Nord mantiene relazioni diplomatiche strette soprattutto con Cina e Russia, suoi principali alleati e partner economici, in un contesto di isolamento internazionale dovuto al programma nucleare nordcoreano e alle sanzioni internazionali."
   ],
