   "sez": "economia",
   "titolo": "Le azioni di BT salgono dopo risultati migliori delle attese",
   "orig": "BT shares rally as investors sense ‘show me the money’ moment",
   "lead": "Le azioni della società di telecomunicazioni britannica BT sono salite in borsa dopo la pubblicazione di profitti superiori alle attese degli analisti. Gli investitori interpretano il risultato come un segnale che i pesanti investimenti nella rete dell'azienda stanno iniziando a ripagare. L'andamento positivo del titolo arriva in un momento di generale ripresa dei mercati, alimentata anche da fattori come il calo dei prezzi del petrolio e il ritorno di interesse da parte degli investitori internazionali. Lo riferisce Financial Times.",
   "more": [
    "BT è una delle principali società di telecomunicazioni del Regno Unito, impegnata negli ultimi anni in un vasto piano di investimenti per estendere la rete di fibra ottica nel paese. I risultati finanziari delle grandi aziende di infrastrutture digitali sono spesso osservati dagli investitori come indicatore della sostenibilità di questi investimenti a lungo termine."
   ],
