   "id": "z8eb9cf91",
   "sez": "mondo",
   "titolo": "Corte d'appello sudcoreana si pronuncerà il 26 gennaio sul caso della legge marziale dell'ex presidente Yoon",
   "orig": "Appeals court to rule on ex-President Yoon's martial law case on Jan. 26",
   "lead": "Una corte d'appello sudcoreana ha annunciato che emetterà la sua sentenza il 26 gennaio sul caso relativo alla dichiarazione di legge marziale imposta dall'ex presidente Yoon Suk-yeol. Il caso riguarda l'accusa contro l'ex presidente per aver tentato di imporre la legge marziale, un episodio che ha scosso la politica sudcoreana. La decisione della corte sarà quindi attesa nei prossimi mesi, con importanti implicazioni per il futuro politico e giudiziario di Yoon. Lo riferisce Yonhap.",
   "more": [
    "Nel dicembre 2024 l'allora presidente sudcoreano Yoon Suk-yeol aveva dichiarato per alcune ore la legge marziale, provocando una forte crisi istituzionale e il successivo processo di impeachment. L'episodio ha portato a procedimenti giudiziari penali contro Yoon per insurrezione e abuso di potere, ancora in corso davanti ai tribunali sudcoreani."
   ],
