   "id": "zea2937c4",
   "sez": "mondo",
   "titolo": "Guinea, vietata l'estrazione d'oro artigianale incontrollata a Siguiri",
   "orig": "Interdiction de l’orpaillage anarchique à Siguiri : « c’est une opportunité de réformer le secteur et mettre en place un encadrement sérieux » (Amadou Bah)",
   "lead": "Il governo della Guinea ha annunciato il divieto totale delle attività di estrazione artigianale dell'oro non autorizzate nella regione di Siguiri, accompagnato dal dispiegamento permanente delle forze di sicurezza, a causa delle conseguenze ambientali e sociali di questa pratica. Secondo Amadou Bah, la decisione rappresenta un'opportunità per riformare il settore e introdurre una regolamentazione più rigorosa. La misura ha riacceso il dibattito sulla gestione del settore aurifero artigianale, i suoi effetti economici e il suo impatto ambientale nella regione dell'Alta Guinea.",
   "more": [
    "L'estrazione artigianale dell'oro, praticata da migliaia di persone in diverse regioni dell'Africa occidentale, è spesso fonte di reddito per comunità povere ma comporta gravi rischi ambientali, come la deforestazione e l'inquinamento da mercurio nei corsi d'acqua, oltre a condizioni di lavoro talvolta precarie o pericolose per i minatori."
   ],
