   "titolo": "Nuova Zelanda, elezioni al fotofinish: cosa c'è da sapere",
   "orig": "New Zealand braces for knife-edge election: What you need to know",
   "lead": "La Nuova Zelanda si prepara a elezioni generali molto incerte, in cui i partiti minori potrebbero risultare decisivi dato che i principali contendenti, entrambi guidati da leader di nome Chris, sono attesi al di sotto della maggioranza necessaria per governare da soli. Secondo le fonti, il sostegno ai due grandi partiti sta calando a causa della diffusa insoddisfazione per la situazione economica del paese, lasciando spazio ai partiti più piccoli che potrebbero orientare la formazione del prossimo governo.",
   "more": [
    "Il sistema elettorale neozelandese, di tipo proporzionale misto, favorisce da anni governi di coalizione, in cui i partiti minori ottengono spesso un potere negoziale significativo nella formazione dell'esecutivo, anche quando raccolgono una quota limitata di voti complessivi."
   ],
