   "sez": "mondo",
   "titolo": "Un soldato britannico ricattato con foto intime durante un'esercitazione NATO in Estonia",
   "orig": "Nude blackmail of British soldier at Tapa raises security concerns",
   "lead": "Un caporale britannico impegnato in un'esercitazione NATO a Tapa, in Estonia, ha ignorato l'ordine di rimuovere la scheda SIM dal proprio telefono ed è stato successivamente hackerato e ricattato con foto intime, secondo quanto riportato dal settimanale estone Eesti Ekspress. L'episodio ha suscitato preoccupazioni sulla sicurezza informatica delle truppe alleate di stanza nella base, sede di importanti esercitazioni militari NATO vicino al confine con la Russia. Lo riferisce ERR News.",
   "more": [
    "La base di Tapa, in Estonia, ospita truppe multinazionali della NATO nel quadro del rafforzamento della presenza alleata sul fianco orientale dopo l'invasione russa dell'Ucraina. Episodi di spionaggio informatico o ricatto contro militari occidentali di stanza vicino ai confini russi sono stati segnalati in diverse occasioni come possibile tattica di intelligence ostile."
   ],
