   "titolo": "I paesi della Comunità dell'Africa Orientale si coordinano contro i rischi del fenomeno El Niño",
   "orig": "EAC bloc develops joint strategies in preparedness for El Niño threats",
   "lead": "Funzionari della gestione dei disastri degli stati membri della Comunità dell'Africa Orientale (EAC) si sono incontrati a Nairobi, in Kenya, per discutere strategie comuni in previsione delle piogge intense legate al fenomeno El Niño attese nella regione. L'incontro, iniziato il 4 novembre, è proseguito in una seconda giornata di lavori dedicata alla definizione di piani congiunti di risposta alle emergenze climatiche. Lo riferisce Daily News (Tanzania).",
   "more": [
    "El Niño è un fenomeno climatico ciclico che altera le temperature oceaniche del Pacifico, provocando in alcune regioni dell'Africa orientale piogge più intense del normale, con rischio di inondazioni, frane e danni alle infrastrutture e all'agricoltura locale."
   ],
