  "zfc31da37": "The Citizen riporta la dichiarazione ufficiale del Tesoro sudafricano sugli effetti della revisione del Pil.",
  "z0fcec912": "14ymedio riporta l'analisi di un organismo economico sul divario tra settore pubblico e privato a Cuba.",
  "z433b9785": "Meduza riprende un'inchiesta del Financial Times sul cambiamento di rotta di due petroliere russe dirette negli Stati Uniti.",
  "zaa902957": "IPN riporta l'annuncio del ministero moldavo sul finanziamento della Banca Mondiale per le strade regionali.",
  "zb85925b1": "The Times of Central Asia riporta la richiesta ufficiale del Kazakhstan alla Russia sulla riapertura dell'oleodotto.",
  "z229f1753": "Myanmar Now riporta la selettività della Cina nella riapertura dei valichi, escludendo quelli controllati da specifici gruppi armati.",
  "z0dee300c": "Rai News segnala le tensioni interne al Partito repubblicano dopo la sconfitta elettorale, con Hegseth nel mirino.",
  "z5cc11c7f": "Hong Kong Free Press riporta la richiesta cinese di estradizione e le preoccupazioni delle organizzazioni per i diritti umani.",
  "z0545fcf3": "Il Guardian riporta le conclusioni della commissione parlamentare britannica sulla dipendenza dalla Cina per i minerali critici.",
  "z434964d3": "La Nouvelle Tribune riporta la decisione della città californiana sulla registrazione delle unioni poliamorose.",
  "ze9abd860": "Tagesschau riporta i primi esiti delle indagini che escludono il coinvolgimento di terzi nella morte di Aiwanger.",
  "z5667f2ce": "Al Jazeera sottolinea il peso del record di seggi ottenuto dai partiti arabi nel sostenere la candidatura di Eisenkot.",
  "z6be86134": "Vatican News riporta le parole del cardinale Parolin sul significato del viaggio papale in America Latina.",
  "zbac7fbe7": "allAfrica segnala le possibili conseguenze della sentenza sulla partecipazione dell'ADC alle elezioni del 2027.",
  "zb6cc6462": "Brújula Digital sottolinea il collegamento tra l'approvazione dei crediti e l'accordo precedente della Bolivia con il Fmi.",
  "z973eacf7": "Cronaca di un conflitto interno al Pcf tra la linea ufficiale e i deputati.",
  "zaafd934d": "Resoconto degli sviluppi dell'incidente in corso con focus sulle operazioni di soccorso.",
  "z54761a1a": "Dichiarazione istituzionale mirata a rassicurare sulle relazioni bilaterali indipendentemente dall'esito elettorale americano.",
  "zdab25609": "Cronaca dei preparativi della nazionale bhutanese per una competizione regionale importante.",
  "zcadbdda4": "Resoconto della composizione della delegazione russa per un incontro diplomatico promosso dalla signora Trump.",
  "zdb2e1458": "Atto di rappresaglia amministrativa russo verso un'organizzazione politica georgiana di opposizione.",
  "z8ef1d7d1": "Cronaca di una visita diplomatica su sfondo di divergenze su questioni etiche e religiose tra i due alleati regionali.",
  "zd4d4a9b6": "Copertura dei disordini pubblici in corso durante proteste nazionali su questioni economiche.",
  "zdb42f3f6": "Presentazione di un nuovo strumento di pianificazione dell'adattamento ai rischi climatici rivolto ad amministratori urbani africani.",
  "zb2a91065": "Comunicazione della lista convocati con novità e assenze rilevanti in vista di appuntamenti qualificanti.",
  "z405ec8b5": "Annuncio della leadership militare tedesca in un momento di riassetto strategico dell'esercito.",
  "z735fde4b": "Comunicazione di pledging su finanziamenti per programmi educativi umanitari nonostante tagli globali agli aiuti.",
  "z83adcac2": "Discussione pubblica su questioni di giustizia penale e protezione dei diritti fondamentali.",
  "za0929b78": "Denuncia di discriminazione nell'erogazione degli aiuti umanitari nel campo profughi.",
  "zbbcd315b": "Cronaca della fase processuale su accuse di frode finanziaria nei confronti dell'imprenditore austriaco."
